import math

sky_pixels = []
for y in range(0, 900):
    for x in range(W):
        p_ = get(x, y)
        if p_[2] == 255 and p_[0] > 140 and p_[1] > 180:
            sky_pixels.append((x, y, p_))

print(f"Got {len(sky_pixels)} sky pixels")

def evaluate(focal, top_R=146, top_G=190, hor_R=191, hor_G=217, B=255):
    errs = []
    for x, y, p_ in sky_pixels[:10000]:
        dx = x - W/2
        dy = H/2 - y
        elev = math.atan2(dy, math.sqrt(dx*dx + focal*focal))
        max_elev = math.atan2(H/2, focal)
        t = 1 - elev/max_elev
        est_R = top_R + (hor_R - top_R) * t
        est_G = top_G + (hor_G - top_G) * t
        errs.append((est_R - p_[0])**2 + (est_G - p_[1])**2)
    return sum(errs) / len(errs)

# Best focal
for focal in [800, 900, 950, 1000, 1050, 1100, 1150, 1200, 1250, 1300, 1400]:
