#include <stdio.h>
#include <math.h>

#define W 2400
#define H 1800

static inline void emit(int r, int g, int b) {
    printf("%d %d %d\n", r, g, b);
}

int main(void) {
    FILE *f = freopen("reconstructed.ppm", "w", stdout);
    if (!f) return 1;
    printf("P3\n%d %d\n255\n", W, H);

    const float focal = 1050.0f;
    const float max_elev_sin = (H/2.0f) / sqrtf((H/2.0f)*(H/2.0f) + focal*focal);
    const float top_R = 146.0f, top_G = 190.0f;
    const float hor_R = 192.0f, hor_G = 218.0f;

    for (int y = 0; y < H; y++) {
        for (int x = 0; x < W; x++) {
            int r, g, b;
            float dx = x - W/2.0f;
            float dy = H/2.0f - y;
            if (y < 900) {
                // Sky
                float sinv = dy / sqrtf(dx*dx + dy*dy + focal*focal);
                float t = 1.0f - sinv / max_elev_sin;
                if (t < 0) t = 0; else if (t > 1) t = 1;
                r = (int)(top_R + (hor_R - top_R) * t);
                g = (int)(top_G + (hor_G - top_G) * t);
                b = 255;
            } else {
                // Floor with checker
                float fdy = y - 900.0f;
                float wx = 1.5f * dx / fdy;
                float wz = 1200.0f / fdy;
                int fx = (int)floorf(wx);
                int fz = (int)floorf(wz);
                int parity = ((fx + fz) & 1);
                // Rule: parity even -> D, odd -> L
                if (parity == 0) {
                    r = 67; g = 67; b = 67;
                } else {
                    r = 152; g = 152; b = 152;
                }
            }
            emit(r, g, b);
        }
    }
    fclose(f);
    return 0;
}

