#include <math.h>

#define W 2400
#define H 1800

static const float focal = 1050.0f;
static const float max_elev_sin = (H/2.0f) / sqrtf((H/2.0f)*(H/2.0f) + focal*focal);
static const float top_R = 146.0f, top_G = 190.0f;
static const float hor_R = 192.0f, hor_G = 218.0f;
static const float sky_t_factor = 0.55f;

int main(void) {
    FILE *out = freopen("reconstructed.ppm", "w", stdout);
    if (!out) return 1;
    fprintf(out, "P3\n%d %d\n255\n", W, H);

    // Red sphere
    const float rx_cx = 1248.0f, rx_cy = 950.0f, rx_r = 141.0f;
    // Red shadow ellipse (on floor)
    const float rsh_cx = 1188.0f, rsh_cy = 1005.0f, rsh_r1 = 175.0f, rsh_r2 = 175.0f;
    // Dark sphere/shadow region
    const float dk_cx = 870.0f, dk_cy = 1290.0f;
    const float dk_a = 410.0f, dk_b = 145.0f, dk_angle = -0.50f;

    // Light direction for red sphere (projected): bright spot upper right
    const float lL_x = 0.5f, lL_y = -0.5f, lL_z = 0.707f;  // normalized

    for (int y = 0; y < H; y++) {
        for (int x = 0; x < W; x++) {
            int r, g, b;
            float dx = x - W/2.0f;
            float dy = H/2.0f - y;

            // Sky color (default)
            float sinv = dy / sqrtf(dx*dx + dy*dy + focal*focal);
            float t = 1.0f - sinv / max_elev_sin;
            if (t < 0) t = 0; else if (t > 1) t = 1;
            int sky_r = (int)(top_R + (hor_R - top_R) * t);
            int sky_g = (int)(top_G + (hor_G - top_G) * t);
            int sky_b = 255;

            r = sky_r; g = sky_g; b = sky_b;

            // Floor color
            int floor_r, floor_g, floor_b;
            if (y >= 900) {
                float fdy = y - 900.0f;
                float wx = 1.5f * (x - W/2.0f) / fdy;
                float wz = 1200.0f / fdy;
                int fx = (int)floorf(wx);
                int fz = (int)floorf(wz);
                int parity = ((fx + fz) & 1);
                if (parity == 0) {
                    floor_r = 67; floor_g = 67; floor_b = 67;
                } else {
                    floor_r = 152; floor_g = 152; floor_b = 152;
                }
                r = floor_r; g = floor_g; b = floor_b;
            }

            // Check dark sphere/shadow region (overrides floor in this area)
            {
                float cdx = x - dk_cx;
                float cdy = y - dk_cy;
                float ca = cdx * cosf(dk_angle) + cdy * sinf(dk_angle);
                float cb = -cdx * sinf(dk_angle) + cdy * cosf(dk_angle);
                float ea = ca / dk_a;
                float eb = cb / dk_b;
                float e2 = ea * ea + eb * eb;
                if (e2 <= 1.0f) {
                    // Shading: light from upper-right
                    // ea>0 means right side (lighter gray 46)
                    // ea<0 means left side (darker 20)
                    int gray;
                    if (ea > 0) {
                        // Right side: lighter
                        gray = (int)(20 + (46 - 20) * (1.0f - e2));
                    } else {
                        // Left side: darker
                        gray = (int)(46 - (46 - 20) * (1.0f - e2));
                    }
                    r = gray; g = gray; b = gray;
                }
            }

            // Check red shadow
            {
                float rdx = (x - rsh_cx) / rsh_r1;
                float rdy = (y - rsh_cy) / rsh_r2;
                if (rdx*rdx + rdy*rdy <= 1.0f) {
                    r = 51; g = 10; b = 10;
                }
            }

            // Check red sphere body
            {
                float nxd = (x - rx_cx) / rx_r;
                float nyd = (y - rx_cy) / rx_r;
                float d2 = nxd*nxd + nyd*nyd;
                if (d2 <= 1.0f) {
                    // Sphere shading - Lambertian
                    float nz = sqrtf(1.0f - d2);
                    float intensity = nxd * lL_x + nyd * lL_y + nz * lL_z;
                    if (intensity < 0) intensity = 0;
                    // ambient = 51, max = ~196
                    float fr = 51 + 145 * intensity;
                    float fg = 10 + 28 * intensity;
                    float fb = 10 + 28 * intensity;
                    r = (int)fr;
                    g = (int)fg;
                    b = (int)fb;
                }
            }

            printf("%d %d %d\n", r, g, b);
        }
    }
    return 0;
}

